        // event query
        request = new EqlSearchRequest().indices("test-*").query("process where true");
        response = client().execute(EqlSearchAction.INSTANCE, request).get();
        assertThat(response.hits().events().size(), equalTo(5));
        for (int i = 0; i < 5; i++) {
