        );

        for (int i = 0; i < 5; i++) {
            int val = i * 2;
            remoteClient.prepareIndex("test-1-remote")
                .setId(Integer.toString(i))
                .setSource("@timestamp", 100000 + val, "event.category", "process", "key", "same", "value", val)
